--- Resolve a route reputation requirement into a common progress model.
-- If type is omitted, major factions and friendship reputations are detected before standard standings.
---@param requirement table|nil expects factionID, level, and optionally type
---@return table|nil progress
---@return number|nil factionID
---@return number|nil targetLevel
function APR:GetReputationRequirement(requirement)
    if type(requirement) ~= "table" then
        return nil, nil, nil
    end

    local factionID = tonumber(requirement.factionID)
    local targetLevel = tonumber(requirement.level)
    if not factionID or not targetLevel then
        return nil, factionID, targetLevel
    end

    local requestedType = NormalizeReputationType(requirement.type)
    if requirement.type ~= nil and not requestedType then
        return nil, factionID, targetLevel
    end

    if requestedType then
        local resolver
        if requestedType == APR.REPUTATION_TYPE.Renown then
            resolver = GetRenownReputationProgress
        elseif requestedType == APR.REPUTATION_TYPE.Friendship then
            resolver = GetFriendshipReputationProgress
        elseif requestedType == APR.REPUTATION_TYPE.Standard then
            resolver = GetStandardReputationProgress
        end
        local progress = resolver(factionID, targetLevel)
        return progress or {
            factionID = factionID,
            targetLevel = targetLevel,
            type = requestedType,
        }, factionID, targetLevel
    end

    -- Keep detection ordered and live without allocating dispatch/order tables
    -- on every completion, text and progress-bar query.
    local progress = GetRenownReputationProgress(factionID, targetLevel)
        or GetFriendshipReputationProgress(factionID, targetLevel)
        or GetStandardReputationProgress(factionID, targetLevel)
    if progress then return progress, factionID, targetLevel end

    return {
        factionID = factionID,
        targetLevel = targetLevel,
        type = APR.REPUTATION_TYPE.Standard,
    }, factionID, targetLevel
end--[[APR_DIAG]]; APR.GetReputationRequirement = APRTrace("APR-Core/utils/PlayerUtils.lua:346:APR:GetReputationRequirement#25", APR.GetReputationRequirement)--[[/APR_DIAG]]

