--- Return the 12.1 item-targeting context for an owned route item, when a spell is targeting an item.
--- Older clients simply return nil and retain the pre-12.1 tooltip.
---@param itemID number
---@return table|nil
function APR:GetTargetSpellItemContext(itemID)
    if not C_Spell or type(C_Spell.TargetSpellChecksItemCondition) ~= "function" or
        not C_Item or type(C_Item.DoesItemMatchSpellItemCondition) ~= "function" or
        not C_Spell.TargetSpellChecksItemCondition() then
        return nil
    end

    local itemLocation = GetOwnedItemLocation(tonumber(itemID))
    if not itemLocation then
        return { matches = false }
    end

    local matches = C_Item.DoesItemMatchSpellItemCondition(itemLocation)
    local cursorType, _, _, targetSpellID = GetCursorInfo()
    local description
    if cursorType == "spell" and targetSpellID and type(C_Spell.GetSpellDescriptionForItemLocation) == "function" then
        description = C_Spell.GetSpellDescriptionForItemLocation(targetSpellID, itemLocation)
    end

    return {
        description = description,
        itemLocation = itemLocation,
        matches = matches == true,
        spellID = targetSpellID,
    }
end--[[APR_DIAG]]; APR.GetTargetSpellItemContext = APRTrace("APR-Core/utils/PlayerUtils.lua:523:APR:GetTargetSpellItemContext#34", APR.GetTargetSpellItemContext)--[[/APR_DIAG]]

--- Evaluate a route action using non-secret booleans whenever cooldown restrictions are active.
---@param actionType string
---@param actionID number|string
---@param ignoreCooldown boolean|nil
---@param ignoreGlobalCooldown boolean|nil Navigation may wait for the current global cooldown.
---@return boolean usable
---@return string|nil reason
function APR:GetRouteActionUsability(actionType, actionID, ignoreCooldown, ignoreGlobalCooldown)
    actionID = tonumber(actionID)
    if not actionID then
        return false, "invalid"
    end

    if actionType == "spell" then
        if not C_Spell or not C_Spell.GetSpellInfo or not C_Spell.GetSpellInfo(actionID) then
            return false, "unknown"
        end
        if self.IsSpellKnown and not self:IsSpellKnown(actionID) then
            return false, "unknown"
        end

        if C_Spell.IsSpellUsable then
            local isUsable = C_Spell.IsSpellUsable(actionID)
            if isUsable == false then
                return false, "unusable"
            end
        end

        if ignoreCooldown then
            return true
        end

        local cooldownInfo = C_Spell.GetSpellCooldown and C_Spell.GetSpellCooldown(actionID) or nil
        if not cooldownInfo then
            return true
        end

        if ignoreGlobalCooldown then
            -- A normal cast briefly starts every spell's global cooldown. It
            -- does not remove teleport destinations from a travel plan.
            if C_Spell.GetSpellCooldownDuration then
                local durationObject = C_Spell.GetSpellCooldownDuration(actionID, true)
                if durationObject and durationObject.IsZero then
                    local zero = durationObject:IsZero()
                    if (self.CanAccessValue and not self:CanAccessValue(zero))
                        or (issecretvalue and issecretvalue(zero)) then return false, "restricted" end
                    return zero == true, zero ~= true and "cooldown" or nil
                end
            else
                local global = C_Spell.GetSpellCooldown(61304)
                local start, duration = cooldownInfo.startTime, cooldownInfo.duration
                if global and (not self.CanAccessValue or (self:CanAccessValue(start)
                    and self:CanAccessValue(duration) and self:CanAccessValue(global.startTime)
                    and self:CanAccessValue(global.duration)))
                    and type(duration) == "number" and duration > 0
                    and start == global.startTime and duration == global.duration then return true end
            end
        end

        -- isActive was added in 12.0.1 specifically as a never-secret decision value.
        if cooldownInfo.isActive ~= nil then
            return cooldownInfo.isActive == false, cooldownInfo.isActive and "cooldown" or nil
        end

        -- 12.0.0 has DurationObject support but predates the never-secret isActive field.
        if C_Spell.GetSpellCooldownDuration then
            local cooldownDuration = C_Spell.GetSpellCooldownDuration(actionID)
            if cooldownDuration and cooldownDuration.IsZero then
                local isZero = cooldownDuration:IsZero()
                if isZero then
                    return true
                end
                return false, "cooldown"
            end
        end

        -- Legacy fallback: compare values only when the client says they are accessible.
        local duration = cooldownInfo.duration
        if self.CanAccessValue and not self:CanAccessValue(duration) then
            return false, "restricted"
        end
        return type(duration) ~= "number" or duration <= 0, type(duration) == "number" and duration > 0 and
            "cooldown" or nil
    end

    if actionType == "item" then
        local hasToy = PlayerHasToy and PlayerHasToy(actionID) or false
        if hasToy then
            -- Learned toys live in the collection, so their bag count is irrelevant.
            -- Ownership alone does not prove this character can use the toy yet.
            local toyUsable = C_ToyBox and C_ToyBox.IsToyUsable and C_ToyBox.IsToyUsable(actionID)
            if toyUsable ~= true then
                return false, toyUsable == false and "unusable" or "pending_data"
            end
        else
            local itemCount = C_Item and C_Item.GetItemCount and C_Item.GetItemCount(actionID)
                or (GetItemCount and GetItemCount(actionID)) or 0
            if self.CanAccessValue and not self:CanAccessValue(itemCount) then return false, "restricted" end
            if itemCount <= 0 then return false, "missing" end
        end

        if C_Item and C_Item.IsUsableItem then
            local isUsable = C_Item.IsUsableItem(actionID)
            if isUsable == false then
                return false, "unusable"
            end
        end

        if ignoreCooldown then
            return true
        end

        local startTime, duration, enabled
        if C_Item and C_Item.GetItemCooldown then
            startTime, duration, enabled = C_Item.GetItemCooldown(actionID)
        elseif C_Container and C_Container.GetItemCooldown then
            startTime, duration, enabled = C_Container.GetItemCooldown(actionID)
        elseif GetItemCooldown then
            startTime, duration, enabled = GetItemCooldown(actionID)
        end

        -- A restricted cooldown is unknown, not permission to spend the item.
        if self.CanAccessValue and (not self:CanAccessValue(startTime)
            or not self:CanAccessValue(duration) or not self:CanAccessValue(enabled)) then
            return false, "restricted"
        end
        local cooldownEnabled = enabled == true or enabled == 1
        local isActive = cooldownEnabled and type(startTime) == "number" and startTime > 0 and
            type(duration) == "number" and duration > 0
        return not isActive, isActive and "cooldown" or nil
    end

    return false, "invalid"
end--[[APR_DIAG]]; APR.GetRouteActionUsability = APRTrace("APR-Core/utils/PlayerUtils.lua:557:APR:GetRouteActionUsability#35", APR.GetRouteActionUsability)--[[/APR_DIAG]]

-- Timing may be secret on modern clients. Never format or compare it until
-- accessibility is checked; the cooldown widget can still display that timing.
function APR:GetActionAvailabilityText(actionType, actionID, includeRemaining)
    local usable, reason = self:GetRouteActionUsability(actionType, actionID, true)
    if not usable then
        if reason == "missing" then return L["ACTION_ITEM_MISSING"] end
        if reason == "unknown" then return L["ACTION_SPELL_UNKNOWN"] end
        return self:GetRouteActionStatusText(reason)
    end
    local start, duration, enabled, active, modRate
    if actionType == "spell" then
        local info = C_Spell and C_Spell.GetSpellCooldown and C_Spell.GetSpellCooldown(actionID)
        if not info then return nil end
        start, duration, enabled, active, modRate = info.startTime, info.duration, info.isEnabled, info.isActive, info.modRate
    elseif actionType == "item" then
        local getCooldown = C_Item and C_Item.GetItemCooldown or C_Container and C_Container.GetItemCooldown
        if not getCooldown then return nil end
        start, duration, enabled = getCooldown(actionID)
    else
        return nil
    end
    if self.CanAccessValue and (not self:CanAccessValue(enabled) or not self:CanAccessValue(active)) then return nil end
    if enabled == false or enabled == 0 or active == false then return nil end
    for _, value in pairs({ start, duration, modRate }) do
        if self.CanAccessValue and not self:CanAccessValue(value) then
            return active == true and L["ACTION_COOLDOWN"] or nil
        end
    end
    if type(start) ~= "number" or type(duration) ~= "number" then
        return active and L["ACTION_COOLDOWN"] or nil
    end
    -- Avoid adding/removing an instruction on every global cooldown.
    if start <= 0 or duration <= 1.5 then return nil end
    local remaining = duration / (type(modRate) == "number" and modRate > 0 and modRate or 1) - (GetTime() - start)
    if remaining <= 0 then return nil end
    if not includeRemaining then return L["ACTION_COOLDOWN"] end
    remaining = math.ceil(remaining)
    return string.format(L["ACTION_AVAILABLE_IN"], string.format("%d:%02d", math.floor(remaining / 60), remaining % 60))
end--[[APR_DIAG]]; APR.GetActionAvailabilityText = APRTrace("APR-Core/utils/PlayerUtils.lua:687:APR:GetActionAvailabilityText#36", APR.GetActionAvailabilityText)--[[/APR_DIAG]]

function APR:GetRouteActionStatusText(reason)
    local messages = {
        cooldown = _G.SPELL_FAILED_NOT_READY,
        invalid = _G.SPELL_FAILED_BAD_TARGETS,
        missing = _G.ERR_ITEM_NOT_FOUND or _G.SPELL_FAILED_ITEM_NOT_FOUND,
        restricted = _G.SPELL_FAILED_NOT_READY,
        unknown = _G.SPELL_FAILED_NOT_KNOWN,
        unusable = _G.SPELL_FAILED_NOT_HERE or _G.SPELL_FAILED_NOT_READY,
    }
    return messages[reason]
end--[[APR_DIAG]]; APR.GetRouteActionStatusText = APRTrace("APR-Core/utils/PlayerUtils.lua:725:APR:GetRouteActionStatusText#37", APR.GetRouteActionStatusText)--[[/APR_DIAG]]
